NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Malachi'

CHAPTERS = {
    1: {
        1: 'Profeettasana. Herran sana Israelille, Malakian kautta.',
        2: 'Olen rakastanut teitä, sanoo Herra. Mutta sanotte: "Missä olet osoittanut rakkautesi meihin?" Eikö Eesau ollut Jaakobin veli – tämä on Herran sana – ja Jaakobia rakastin,',
        3: 'mutta Eesauta vihasin; ja tein hänen vuorensa autioiksi ja annoin hänen perintöosansa erämaan sakaaleille.',
        4: 'Jos Edom sanoo: "Olemme ruhjotut, mutta rakennamme rauniot jälleen", niin Herra Sebaot sanoo näin: He rakentakoot, mutta minä revin maahan. Heidän nimensä olkoon: "jumalattomuuden maa" ja "kansa, johon Herra on vihastunut iankaikkisesti."',
        5: 'Silmänne näkevät sen, ja sanotte: " Herra on suuri Israelin rajojen ulkopuolellakin."',
        6: 'Poika kunnioittakoon isää ja palvelija isäntäänsä. Mutta jos minä olen isä, missä on kunnioitukseni? Ja jos minä olen Herra, missä on pelkoni? sanoo Herra Sebaot teille, te papit, jotka pidätte halpana nimeni. Mutta te sanotte: "Miten olemme pitäneet nimesi halpana?"',
        7: 'Siten, että tuotte alttarilleni saastutettua leipää. Mutta sanotte: "Miten olemme sinut saastuttaneet?" Siten, että sanotte: " Herran pöytä on pidettävä halpana."',
        8: 'Kun te tuotte uhriksi sokean eläimen, se ei ole paha! Kun tuotte ontuvan ja sairaan, se ei ole paha! Vie se maaherrallesi: mieltyykö hän sinuun, ja onko hän sinulle suosiollinen? sanoo Herra Sebaot.',
        9: 'Mutta nyt: lepyttäkää Jumalaa, että hän meitä armahtaisi. Tällaista on kädestänne tullut. Olisiko hän teille suosiollinen? sanoo Herra Sebaot.',
        10: 'Jospa olisi teidän joukossanne joku, joka sulkisi ovet, ettette pitäisi alttarillani tulta turhaan! Ei ole minulla mielisuosiota teihin, sanoo Herra Sebaot, enkä mielly ruokauhriin, joka tulee kädestänne.',
        11: 'Sillä auringon noususta sen laskuun asti on nimeni oleva suuri pakanain seassa, ja joka paikassa uhrataan ja tuodaan nimeni kunniaksi puhdas ruokauhri. Sillä nimeni on oleva suuri pakanain seassa, sanoo Herra Sebaot.',
        12: 'Mutta te häpäisette sen, kun sanotte: "Herran pöytä on saastutettu, ja sen hedelmän syönti on pidettävä halpana."',
        13: 'Mutta te sanotte: "Mikä vaiva!" ja halveksitte sitä, sanoo Herra Sebaot, ja tuotte ryöstettyä, ontuvaa ja sairasta – tuotte sellaista uhrilahjaksi. Minäkö miellyn ottamaan sen kädestänne? sanoo Herra.',
        14: 'Kirottu olkoon pettäjä, jolla on laumassaan koiraspuoli ja joka on luvannut sen, mutta uhraakin Herralle viallisen. Sillä suuri kuningas olen minä, sanoo Herra Sebaot, ja nimeni on pelottava pakanain keskuudessa.',
    },
    2: {
        1: 'Mutta nyt teille tämä käsky, te papit!',
        2: 'Jos ette kuule ja paina sydämeenne, että annatte kunnian nimelleni, sanoo Herra Sebaot, lähetän teitä vastaan kirouksen ja kiroan teille suodut siunaukset. Olenkin ne jo kironnut, sillä te ette ole painaneet tätä sydämeenne.',
        3: 'Katso, kiellän teiltä jälkeläiset, ja viskelen sontaa kasvoillenne, ruokasulaa juhlauhreistanne, ja teidät kannetaan sen kanssa pois.',
        4: 'Tulette tietämään, että olen lähettänyt teille tämän käskyn, jotta liittoni Leevin kanssa pysyisi, sanoo Herra Sebaot.',
        5: 'Liittoni hänen kanssaan oli elämä ja rauha, ja annoin sen hänelle peloksi, niin että hän pelkäsi minua ja kunnioitti nimeäni.',
        6: 'Oikea opetus oli hänen suussaan, eikä vääryyttä tavattu hänen huuliltaan. Rauhassa ja vilpittömästi hän vaelsi kanssani, ja monia hän käänsi pois syntiä tekemästä.',
        7: 'Sillä papin huulet säilyttävät tiedon, ja hänen suustaan etsitään opetus, sillä hän on Herran Sebaotin sanansaattaja.',
        8: 'Mutta te olette poikenneet tieltä, olette opetuksellanne saattaneet monet kompastumaan, ja olette turmelleet Leevin liiton, sanoo Herra Sebaot.',
        9: 'Minäkin teen teidät halveksituiksi ja alhaisiksi koko kansalle, koska ette ole pitäneet teitäni, vaan olette katsoneet henkilöön opetuksessa.',
        10: 'Eikö meillä kaikilla ole sama Isä? Eikö sama Jumala ole meitä luonut? Miksi olemme uskottomia toisillemme ja rikomme isiemme liiton?',
        11: 'Juuda on ollut uskoton, Israelissa ja Jerusalemissa on tehty kauhistus. Sillä Juuda on häväissyt Herran pyhäkön, jota Herra rakastaa, ja on nainut vieraan jumalan tyttären.',
        12: 'Hävittäköön Herra siltä mieheltä, joka tämän tekee, Jaakobin telttamajoista valvojan, vastaajan ja Herran Sebaotin uhrilahjan tuojan.',
        13: 'Toiseksi olette tehneet tämän: olette saattaneet Herran alttarin peitetyksi kyynelillä, itkulla ja huokauksilla, niin ettei hän enää käänny uhrilahjojen puoleen eikä mielly ottamaan mitään kädestänne.',
        14: 'Mutta te sanotte: "Kuinka niin?" Sen tähden, että Herra on todistaja sinun ja nuoruutesi vaimon välillä, jolle sinä olet ollut uskoton, vaikka hän on puolisosi, laillinen aviovaimosi.',
        15: 'Ei kukaan, jolla on jäännös Hengestä, ole tehnyt niin. Mutta miksi se yksi? Hän etsi Jumalalta siementä? – Ottakaa vaari hengestänne älkääkä olko uskottomia nuoruutenne vaimolle.',
        16: 'Sillä minä vihaan hylkäämistä, sanoo Herra, Israelin Jumala, ja sitä, joka peittää vaatteensa väkivallalla, sanoo Herra Sebaot. Ottakaa vaari hengestänne älkääkä olko uskottomia.',
        17: 'Te väsytätte Herran puheillanne. Mutta te sanotte: "Miten väsytämme?" Siten, että sanotte: "Jokainen, joka pahaa tekee, on hyvä Herran silmissä, ja niihin hänellä on mielisuosio"; tai: "Missä on tuomion Jumala?"',
    },
    3: {
        1: 'Katso, lähetän sanansaattajani, ja hän on valmistava tien eteeni. Joutuin temppeliinsä on tuleva Herra, jota te etsitte, ja Liiton Enkeli, jota te rakastatte. Katso, hän tulee, sanoo Herra Sebaot.',
        2: 'Mutta kuka kestää hänen tulemisensa päivän, ja kuka voi pysyä, kun hän ilmestyy? Sillä hän on kuin kultasepän tuli ja kuin pesijäin saippua.',
        3: 'Hän istuu ja sulattaa ja puhdistaa hopean, hän puhdistaa Leevin pojat, saa ne puhtaiksi kuin kullan ja hopean ja sitten he tuovat Herralle uhrilahjoja vanhurskaudessa.',
        4: 'Silloin Herralle ovat otollisia Juudan ja Jerusalemin uhrilahjat kuin muinaisina päivinä ja entisinä vuosina.',
        5: 'Lähestyn teitä pitääkseni tuomion ja tulen kiireesti todistajaksi velhoja, avionrikkojia ja väärinvannojia vastaan ja niitä vastaan, jotka sortavat palkkalaista palkanmaksussa, leskeä ja orpoa ja vääntävät vääräksi muukalaisen asian eivätkä pelkää minua, sanoo Herra Sebaot.',
        6: 'Sillä minä, Herra, en muutu, ettekä te, Jaakobin lapset, lopeta.',
        7: 'Isienne päivistä asti te olette poikenneet säädöksistäni ettekä ole noudattaneet niitä. Kääntykää luokseni, niin käännyn teidän luoksenne, sanoo Herra Sebaot. Mutta te sanotte: "Missä asiassa meidän on käännyttävä?"',
        8: 'Riistääkö ihminen Jumalalta? Te kuitenkin riistätte minulta. Mutta te sanotte: "Missä asiassa sinulta riistämme?" Kymmenyksissä ja antimissa.',
        9: 'Te olette kirouksella kirotut, koska te, koko kansa, riistätte minulta.',
        10: 'Tuokaa täydet kymmenykset varastohuoneeseen, että huoneessani olisi ravintoa, ja siten koetelkaa minua, sanoo Herra Sebaot, ettenkö avaa teille taivaan ikkunoita ja vuodata teille siunausta ylenpalttisesti.',
        11: 'Karkotan nuhtelullani teiltä syöjät turmelemasta maanne hedelmää, eikä viiniköynnöksenne kedolla ole hedelmätön, sanoo Herra Sebaot.',
        12: 'Silloin teitä ylistävät autuaiksi kaikki pakanat, sillä te tulette olemaan ihana maa, sanoo Herra Sebaot.',
        13: 'Julkeita ovat puheenne minua vastaan, sanoo Herra. Mutta te sanotte: "Mitä olemme sinua vastaan puhuneet?"',
        14: 'Te sanotte: "Turhaa on palvella Herraa. Mitä hyötyä siitä on ollut, että olemme suorittaneet hänelle säädetyt tehtävät ja että olemme vaeltaneet murheellisina Herran Sebaotin kasvojen edessä.',
        15: 'Nyt me kiitämme julkeitten onnea. Ne, jotka tekevät sitä, mikä on jumalatonta, tulevat rakennetuiksi. He kiusaavat Jumalaa, mutta pelastuvat."',
        16: 'Silloin myös Herraa pelkäävät puhuvat toinen toisensa kanssa, ja Herra tarkkailee ja kuulee. Muistokirja kirjoitetaan hänen edessään niiden hyväksi, jotka pelkäävät Herraa ja pitävät hänen nimensä kunniassa.',
        17: 'He ovat omaisuuteni, sanoo Herra Sebaot, sinä päivänä, jonka teen. Olen heille laupias, niin kuin mies on laupias pojalleen, joka häntä palvelee.',
        18: 'Tulette jälleen näkemään, mikä on ero vanhurskaan ja jumalattoman välillä, sen välillä, joka palvelee Jumalaa, ja sen, joka ei häntä palvele.',
        19: 'Sillä katso: tulee päivä, joka palaa kuin pätsi. Kaikki julkeat ja kaikki, jotka tekevät sitä, mikä on jumalatonta, ovat oljenkorsia. Heidät polttaa se päivä, joka tulee, sanoo Herra Sebaot, niin ettei se jätä heistä juurta eikä oksaa.',
        20: 'Mutta teille, jotka nimeäni pelkäätte, koittaa vanhurskauden aurinko ja parantuminen sen siipien alla, ja käytte ulos ja hypitte kuin navetan syöttövasikat',
        21: 'ja tallaatte jumalattomat. He näet tulevat tomuksi jalkapohjienne alle sinä päivänä, jonka minä teen, sanoo Herra Sebaot.',
        22: 'Muistakaa palvelijani Mooseksen laki, jonka säädin Hoorebilla hänelle koko Israelia varten käskyiksi ja oikeuksiksi.',
        23: 'Katso, minä lähetän teille profeetta Elian, ennen kuin tulee Herran päivä, se suuri ja pelottava.',
        24: 'Hän kääntää jälleen isien sydämet lasten puoleen ja lasten sydämet heidän isiensä puoleen, etten tulisi ja löisi maata kirouksella.',
    },
}
